70	/**
71	 * Sync contest_participants based on a user's option selection.
72	 *
73	 * For checkbox options with linked_contest_id:
74	 *   - value === true → upsert into contest_participants
75	 *   - value === false/null → remove from contest_participants
76	 *
77	 * For multi_select options where individual choices have contest_id:
78	 *   - For each choice with contest_id: if selected → upsert, if not → remove
79	 *
80	 * For select options with linked_contest_id:
81	 *   - If any non-empty value selected → upsert
82	 *   - If value is null/cleared → remove
83	 *
84	 * @param adminClient - Supabase admin client (bypasses RLS)
85	 * @param userId - The user whose enrollment to sync
86	 * @param option - The trip_options row
87	 * @param value - The selection value (true/false, string, string[], or null)
88	 */
89	export async function syncContestEnrollment(
90	  adminClient: SupabaseClient,
91	  userId: string,
92	  option: {
93	    id: string;
94	    option_type: string;
95	    linked_contest_id?: string | null;
96	    choices?: OptionChoice[] | null;
97	  },
98	  value: unknown
99	): Promise<void> {
100	  if (option.option_type === "checkbox") {
101	    if (!option.linked_contest_id) return;
102	    if (value === true) {
103	      await upsertParticipantWithPickemPayment(adminClient, option.linked_contest_id, userId);
104	    } else {
105	      await removeParticipantWithPickemPayment(adminClient, option.linked_contest_id, userId);
106	    }
107	  } else if (option.option_type === "select") {
108	    // Per-choice contest_id (mirrors multi_select): enroll into a choice's
109	    // contest only when that exact choice is the selected value. This is how
110	    // Yes/No opt-ins work — only the "Yes" choice carries a contest_id, so a
111	    // "No" selection correctly un-enrolls instead of enrolling (which the
112	    // whole-option linked_contest_id path below would wrongly do).
113	    const choices = (option.choices || []) as OptionChoice[];
114	    for (const choice of choices) {
115	      if (!choice.contest_id) continue;
116	      if (value === choice.value) {
117	        await upsertParticipantWithPickemPayment(adminClient, choice.contest_id, userId);
118	      } else {
119	        await removeParticipantWithPickemPayment(adminClient, choice.contest_id, userId);
120	      }
121	    }
122	
123	    // Legacy whole-option link: any non-empty value enrolls.
124	    if (option.linked_contest_id) {
125	      if (value && value !== "none" && value !== "") {
126	        await upsertParticipantWithPickemPayment(adminClient, option.linked_contest_id, userId);
127	      } else {
128	        await removeParticipantWithPickemPayment(adminClient, option.linked_contest_id, userId);
129	      }
130	    }
131	  } else if (option.option_type === "multi_select") {
132	    const choices = (option.choices || []) as OptionChoice[];
133	    const selectedValues = Array.isArray(value) ? (value as string[]) : [];
134	
135	    if (option.linked_contest_id) {
136	      if (selectedValues.length > 0) {
137	        await upsertParticipantWithPickemPayment(adminClient, option.linked_contest_id, userId);
138	      } else {
139	        await removeParticipantWithPickemPayment(adminClient, option.linked_contest_id, userId);
140	      }
141	    }
142	
143	    for (const choice of choices) {
144	      if (!choice.contest_id) continue;
145	      if (selectedValues.includes(choice.value)) {
146	        await upsertParticipantWithPickemPayment(adminClient, choice.contest_id, userId);
147	      } else {
148	        await removeParticipantWithPickemPayment(adminClient, choice.contest_id, userId);
149	      }
150	    }
151	  }
152	  // text and number types: no contest linking
153	}
