8	function normalizeQuantityValue(
9	  raw: unknown,
10	  option: { choices?: Array<{ value: string }> | null; max_total?: number | null }
11	): { value: Record<string, number> | null; error?: string } {
12	  if (raw === null || raw === undefined) return { value: null };
13	  if (typeof raw !== "object" || Array.isArray(raw)) {
14	    return { value: null, error: "quantity value must be an object of {choice: count}" };
15	  }
16	  const choiceValues = new Set((option.choices || []).map((c) => c.value));
17	  const out: Record<string, number> = {};
18	  let total = 0;
19	  for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
20	    if (!choiceValues.has(k)) continue;
21	    const n = Number(v);
22	    if (!Number.isFinite(n) || n < 0) {
23	      return { value: null, error: `invalid quantity for ${k}` };
24	    }
25	    const intN = Math.floor(n);
26	    if (intN > 0) {
27	      out[k] = intN;
28	      total += intN;
29	    }
30	  }
31	  if (option.max_total != null && total > option.max_total) {
32	    return { value: null, error: `total quantity exceeds the limit of ${option.max_total}` };
33	  }
34	  // Preserve {} as the "explicitly chose zero" marker; client sends null
35	  // when the user truly wants to clear the row.
36	  return { value: out };
37	}
