130	    const { error: upsertError } = await adminClient
131	      .from("user_option_selections")
132	      .upsert(
133	        { trip_id, user_id: effectiveUserId, option_id, value },
134	        { onConflict: "user_id,option_id" }
135	      );
136	    if (upsertError) return NextResponse.json({ error: upsertError.message }, { status: 500 });
137	  }
138	
139	  // 2. Sync financial charges — always delete existing option-sourced charges first
140	  const { error: deleteChargeError } = await adminClient
141	    .from("financial_transactions")
142	    .delete()
143	    .eq("user_id", effectiveUserId)
144	    .eq("option_id", option_id)
145	    .eq("source", "option");
146	  if (deleteChargeError) return NextResponse.json({ error: deleteChargeError.message }, { status: 500 });
147	
148	  // If value is null (deletion), cascade-clear dependent options, sync contest enrollment, and we're done
149	  if (value === null || value === undefined) {
150	    await Promise.all([
151	      syncContestEnrollment(adminClient, effectiveUserId, option, null),
152	      syncCostItemContestEnrollment(adminClient, effectiveUserId, option_id, null),
153	    ]);
154	
155	    // Find options that depend on this one and clear their selections too
156	    const { data: dependents } = await adminClient
157	      .from("trip_options")
158	      .select("id, option_type, linked_contest_id, choices")
159	      .eq("depends_on_option_id", option_id);
160	
161	    if (dependents && dependents.length > 0) {
162	      const depIds = dependents.map((d) => d.id);
163	      // Batch delete selections and charges for all dependents
164	      await Promise.all([
165	        adminClient
166	          .from("user_option_selections")
167	          .delete()
168	          .eq("user_id", effectiveUserId)
169	          .in("option_id", depIds),
170	        adminClient
171	          .from("financial_transactions")
172	          .delete()
173	          .eq("user_id", effectiveUserId)
174	          .in("option_id", depIds)
175	          .eq("source", "option"),
176	        // Unenroll from each dependent's contest (can't batch — each has different contest_id)
177	        ...dependents.flatMap((dep) => [
178	          syncContestEnrollment(adminClient, effectiveUserId, dep, null),
179	          syncCostItemContestEnrollment(adminClient, effectiveUserId, dep.id, null),
180	        ]),
181	      ]);
182	    }
183	
184	    return NextResponse.json({ success: true });
185	  }
186	
187	  let chargeAmount: number | null = null;
188	  let description = option.name;
189	
190	  if (option.option_type === "checkbox" || option.option_type === "trip_cost") {
191	    if (value === true) {
192	      chargeAmount = option.cost ? Number(option.cost) : null;
193	    }
194	  } else if (option.option_type === "select") {
195	    const choices = (option.choices || []) as Array<{ label: string; value: string; cost?: number }>;
196	    const matched = choices.find((c) => c.value === value);
197	    if (matched && matched.cost) {
198	      chargeAmount = Number(matched.cost);
199	      description = `${option.name}: ${matched.label}`;
200	    }
201	  } else if (option.option_type === "multi_select") {
202	    const choices = (option.choices || []) as Array<{ label: string; value: string; cost?: number }>;
203	    const selectedValues = Array.isArray(value) ? value : [];
204	    let total = 0;
205	    const labels: string[] = [];
206	    for (const val of selectedValues) {
207	      const matched = choices.find((c) => c.value === val);
208	      if (matched && matched.cost) {
209	        total += Number(matched.cost);
210	        labels.push(matched.label);
211	      }
212	    }
213	    if (total > 0) {
214	      chargeAmount = total;
215	      description = `${option.name}: ${labels.join(", ")}`;
216	    }
217	  }
218	  // text and number types: no charge
219	
220	  // Create the charge if there's a cost
221	  if (chargeAmount && chargeAmount > 0) {
222	    const { error: chargeError } = await adminClient
223	      .from("financial_transactions")
224	      .insert({
225	        user_id: effectiveUserId,
226	        trip_id,
227	        type: "charge",
228	        source: "option",
229	        option_id,
230	        description,
231	        amount: chargeAmount,
232	        created_by: user.id,
233	      });
234	    if (chargeError) return NextResponse.json({ error: chargeError.message }, { status: 500 });
235	  }
236	
237	  // 4. Sync contest enrollment (legacy linked_contest_id + new cost_item chain)
238	  await Promise.all([
239	    syncContestEnrollment(adminClient, effectiveUserId, option, value),
240	    syncCostItemContestEnrollment(adminClient, effectiveUserId, option_id, value),
241	  ]);
242	
243	  return NextResponse.json({ success: true });
244	}
